/**
 * Idempotent seed script.
 *
 * Data sources (per model, first found wins):
 *   1. prisma/data/*.json  — generated by `pnpm --filter @elsaad/api db:migrate-excel`
 *   2. @elsaad/shared mock catalog — demo fallback (no DB setup needed)
 * Landing content (Category/Testimonial) comes from @elsaad/shared too.
 *
 * Requires: DATABASE_URL set and schema pushed (`pnpm --filter @elsaad/api db:push`).
 * Run: pnpm --filter @elsaad/api db:seed
 */
import * as fs from "node:fs";
import * as path from "node:path";
import { PrismaClient } from "@prisma/client";
import { categories as contentCategories, testimonials } from "@elsaad/shared";
import {
  mockBrands,
  mockBranches,
  mockCategories,
  mockCompatibilities,
  mockEmployees,
  mockInventory,
  mockModels,
  mockProducts,
} from "@elsaad/shared";
import type {
  BranchOut,
  BrandOut,
  CategoryOut,
  ModelOut,
  ProductOut,
} from "../scripts/migrate-excel";

if (!process.env.DATABASE_URL) {
  console.error(
    "DATABASE_URL is not set. Add it to .env, then run: npx prisma db push && npm run db:seed",
  );
  process.exit(1);
}

const prisma = new PrismaClient();

interface SeedBrand {
  name: string;
  nameAr: string | null;
  slug: string;
  website: string | null;
  description: string | null;
  order: number;
}

interface SeedCategory {
  name: string;
  nameAr: string | null;
  slug: string;
  parentSlug: string | null;
  order: number;
}

interface SeedModel {
  name: string;
  nameAr: string | null;
  slug: string;
  brandSlug: string;
  category: string;
  engineCc: number | null;
  yearFrom: number | null;
}

interface SeedProduct {
  code: string;
  name: string;
  nameEn: string | null;
  description: string | null;
  oemCode: string | null;
  brandSlug: string | null;
  categorySlug: string | null;
  costPrice: number | null;
  wholesalePrice: number | null;
  retailPrice: number | null;
  stock: number | null;
}

interface SeedBranch {
  code: string;
  slug: string;
  nameAr: string;
  nameEn: string | null;
  type: string;
  phone: string | null;
  whatsapp: string | null;
  address: string;
  addressEn: string | null;
  governorate: string;
  openingHours: Record<string, string> | null;
  displayOrder: number;
  managerEmployeeNumber: string | null;
}

interface SeedEmployee {
  employeeNumber: string;
  nameAr: string;
  nameEn: string | null;
  phone: string;
  role: string;
  branchCode: string | null;
}

interface SeedCompat {
  productCode: string;
  modelSlug: string;
  modelBrandSlug: string;
}

const readJson = <T>(name: string): T | null => {
  const file = path.join(process.cwd(), "prisma", "data", name);
  if (!fs.existsSync(file)) return null;
  return JSON.parse(fs.readFileSync(file, "utf8")) as T;
};

const jsonBrands = readJson<BrandOut[]>("brands.json");
const jsonCategories = readJson<CategoryOut[]>("categories.json");
const jsonModels = readJson<ModelOut[]>("models.json");
const jsonProducts = readJson<ProductOut[]>("products.json");
const jsonBranches = readJson<BranchOut[]>("branches.json");

const mockBrandSlugFromId = new Map(mockBrands.map((brand) => [brand.id, brand.slug]));
const mockCategorySlugFromId = new Map(
  mockCategories.map((category) => [category.id, category.slug]),
);
const mockBranchCodeFromId = new Map(mockBranches.map((branch) => [branch.id, branch.code]));
const mockModelBrandSlugFromId = new Map(
  mockModels.map((model) => [model.id, mockBrandSlugFromId.get(model.brandId) ?? ""]),
);

const seedBrands: SeedBrand[] = jsonBrands
  ? jsonBrands.map((brand, index) => ({
      name: brand.name,
      nameAr: brand.nameAr,
      slug: brand.slug,
      website: null,
      description: null,
      order: index,
    }))
  : mockBrands.map((brand) => ({
      name: brand.name,
      nameAr: brand.nameAr,
      slug: brand.slug,
      website: brand.website,
      description: brand.description,
      order: brand.order,
    }));

const seedCategories: SeedCategory[] = jsonCategories
  ? jsonCategories.map((category, index) => ({
      name: category.name,
      nameAr: category.nameAr,
      slug: category.slug,
      parentSlug: null,
      order: index,
    }))
  : mockCategories.map((category) => ({
      name: category.name,
      nameAr: category.nameAr,
      slug: category.slug,
      parentSlug: category.parentId
        ? (mockCategorySlugFromId.get(category.parentId) ?? null)
        : null,
      order: category.order,
    }));

const seedModels: SeedModel[] = jsonModels
  ? jsonModels.map((model) => ({
      name: model.name,
      nameAr: model.nameAr,
      slug: model.slug,
      brandSlug: model.brandSlug,
      category: model.category,
      engineCc: null,
      yearFrom: null,
    }))
  : mockModels.map((model) => ({
      name: model.name,
      nameAr: model.nameAr,
      slug: model.slug,
      brandSlug: mockBrandSlugFromId.get(model.brandId) ?? model.brandId,
      category: model.category,
      engineCc: model.engineCc,
      yearFrom: model.yearFrom,
    }));

const jsonStockByCode = new Map<string, number>();
if (jsonProducts) {
  for (const product of jsonProducts) {
    if (product.stock != null) jsonStockByCode.set(product.code, product.stock);
  }
}

const seedProducts: SeedProduct[] = jsonProducts
  ? jsonProducts.map((product) => ({
      code: product.code,
      name: product.name,
      nameEn: product.nameEn,
      description: product.description,
      oemCode: product.oemCode,
      brandSlug: product.brandSlug,
      categorySlug: product.categorySlug,
      costPrice: product.costPrice,
      wholesalePrice: product.wholesalePrice,
      retailPrice: product.retailPrice,
      stock: product.stock,
    }))
  : mockProducts.map((product) => ({
      code: product.code,
      name: product.name,
      nameEn: product.nameEn,
      description: product.description,
      oemCode: product.oemCode,
      brandSlug: product.brandId ? (mockBrandSlugFromId.get(product.brandId) ?? null) : null,
      categorySlug: product.partCategoryId
        ? (mockCategorySlugFromId.get(product.partCategoryId) ?? null)
        : null,
      costPrice: product.costPrice,
      wholesalePrice: product.wholesalePrice,
      retailPrice: product.retailPrice,
      stock: null,
    }));

const seedBranches: SeedBranch[] = jsonBranches
  ? jsonBranches.map((branch) => ({
      ...branch,
      whatsapp: null,
      addressEn: null,
      managerEmployeeNumber: null,
    }))
  : mockBranches.map((branch) => ({
      code: branch.code,
      slug: branch.slug,
      nameAr: branch.nameAr,
      nameEn: branch.nameEn,
      type: branch.type,
      phone: branch.phone,
      whatsapp: branch.whatsapp,
      address: branch.address,
      addressEn: branch.addressEn,
      governorate: branch.governorate,
      openingHours: branch.openingHours,
      displayOrder: branch.displayOrder,
      managerEmployeeNumber: branch.managerId
        ? branch.managerId.toUpperCase()
        : null,
    }));

const seedEmployees: SeedEmployee[] = mockEmployees.map((employee) => ({
  employeeNumber: employee.employeeNumber,
  nameAr: employee.nameAr,
  nameEn: employee.nameEn,
  phone: employee.phone,
  role: employee.role,
  branchCode: employee.branchId
    ? (mockBranchCodeFromId.get(employee.branchId) ?? null)
    : null,
}));

const seedCompats: SeedCompat[] = jsonProducts
  ? jsonProducts.flatMap((product) =>
      product.modelSlug && product.brandSlug
        ? [
            {
              productCode: product.code,
              modelSlug: product.modelSlug,
              modelBrandSlug: product.brandSlug,
            },
          ]
        : [],
    )
  : mockCompatibilities.flatMap((compat) => {
      const brandSlug = mockModelBrandSlugFromId.get(compat.modelId);
      if (!brandSlug) return [];
      return [
        {
          productCode: compat.productId.replace(/^p-/, "").toUpperCase(),
          modelSlug: compat.modelId.replace(/^m-/, ""),
          modelBrandSlug: brandSlug,
        },
      ];
    });

async function main() {
  for (const [index, category] of contentCategories.entries()) {
    await prisma.category.upsert({
      where: { slug: category.id },
      update: { title: category.title, description: category.description, order: index },
      create: {
        slug: category.id,
        title: category.title,
        description: category.description,
        order: index,
      },
    });
  }

  for (const testimonial of testimonials) {
    const existing = await prisma.testimonial.findFirst({
      where: { name: testimonial.name, text: testimonial.text },
      select: { id: true },
    });
    if (!existing) {
      await prisma.testimonial.create({
        data: {
          name: testimonial.name,
          role: testimonial.role,
          text: testimonial.text,
          published: true,
        },
      });
    }
  }

  const branchByCode = new Map<string, { id: string; slug: string }>();
  const seededBranches: { id: string; code: string; displayOrder: number }[] = [];
  for (const branch of seedBranches) {
    const data = {
      code: branch.code,
      slug: branch.slug,
      nameAr: branch.nameAr,
      nameEn: branch.nameEn,
      type: branch.type,
      phone: branch.phone,
      whatsapp: branch.whatsapp,
      address: branch.address,
      addressEn: branch.addressEn,
      governorate: branch.governorate,
      openingHours: branch.openingHours,
      displayOrder: branch.displayOrder,
      active: true,
    };
    const record = await prisma.branch.upsert({
      where: { slug: branch.slug },
      update: data,
      create: data,
    });
    branchByCode.set(branch.code, { id: record.id, slug: record.slug });
    seededBranches.push({ id: record.id, code: branch.code, displayOrder: branch.displayOrder });
  }

  const employeeByNumber = new Map<string, string>();
  for (const employee of seedEmployees) {
    const branch = employee.branchCode
      ? (branchByCode.get(employee.branchCode) ?? null)
      : null;
    const data = {
      nameAr: employee.nameAr,
      nameEn: employee.nameEn,
      phone: employee.phone,
      role: employee.role,
      branchId: branch?.id ?? null,
      active: true,
    };
    const record = await prisma.employee.upsert({
      where: { employeeNumber: employee.employeeNumber },
      update: data,
      create: { ...data, employeeNumber: employee.employeeNumber },
    });
    employeeByNumber.set(employee.employeeNumber, record.id);
    if (branch) {
      await prisma.employeeBranchAssignment.upsert({
        where: {
          employeeId_branchId: { employeeId: record.id, branchId: branch.id },
        },
        update: { isActive: true },
        create: { employeeId: record.id, branchId: branch.id },
      });
    }
  }

  const brandIdBySlug = new Map<string, string>();
  for (const brand of seedBrands) {
    const data = {
      name: brand.name,
      nameAr: brand.nameAr,
      website: brand.website,
      description: brand.description,
      order: brand.order,
    };
    const record = await prisma.brand.upsert({
      where: { slug: brand.slug },
      update: data,
      create: { ...data, slug: brand.slug },
    });
    brandIdBySlug.set(brand.slug, record.id);
  }

  const categoryIdBySlug = new Map<string, string>();
  const orderedCategories = [
    ...seedCategories.filter((category) => category.parentSlug == null),
    ...seedCategories.filter((category) => category.parentSlug != null),
  ];
  for (const category of orderedCategories) {
    let parentId: string | null = null;
    if (category.parentSlug) {
      parentId = categoryIdBySlug.get(category.parentSlug) ?? null;
      if (!parentId) {
        console.warn(`  [warn] parent "${category.parentSlug}" missing for "${category.slug}"`);
      }
    }
    const data = {
      name: category.name,
      nameAr: category.nameAr,
      order: category.order,
      parentId,
    };
    const record = await prisma.partCategory.upsert({
      where: { slug: category.slug },
      update: data,
      create: { ...data, slug: category.slug },
    });
    categoryIdBySlug.set(category.slug, record.id);
  }

  const modelIdByKey = new Map<string, string>();
  let skippedModels = 0;
  for (const model of seedModels) {
    const brandId = brandIdBySlug.get(model.brandSlug);
    if (!brandId) {
      skippedModels += 1;
      continue;
    }
    const data = {
      name: model.name,
      nameAr: model.nameAr,
      category: model.category,
      engineCc: model.engineCc,
      yearFrom: model.yearFrom,
    };
    const record = await prisma.machineModel.upsert({
      where: { brandId_slug: { brandId, slug: model.slug } },
      update: data,
      create: { ...data, brandId, slug: model.slug },
    });
    modelIdByKey.set(`${model.brandSlug}::${model.slug}`, record.id);
  }

  const productIdByCode = new Map<string, string>();
  for (const product of seedProducts) {
    const brandId = product.brandSlug
      ? (brandIdBySlug.get(product.brandSlug) ?? null)
      : null;
    const partCategoryId = product.categorySlug
      ? (categoryIdBySlug.get(product.categorySlug) ?? null)
      : null;
    const data = {
      name: product.name,
      nameEn: product.nameEn,
      description: product.description,
      oemCode: product.oemCode,
      brandId,
      partCategoryId,
      costPrice: product.costPrice,
      wholesalePrice: product.wholesalePrice,
      retailPrice: product.retailPrice,
      active: true,
      deletedAt: null,
    };
    const record = await prisma.product.upsert({
      where: { code: product.code },
      update: data,
      create: { ...data, code: product.code },
    });
    productIdByCode.set(product.code, record.id);
  }

  let seededCompats = 0;
  let skippedCompats = 0;
  for (const compat of seedCompats) {
    const productId = productIdByCode.get(compat.productCode);
    const modelId = modelIdByKey.get(`${compat.modelBrandSlug}::${compat.modelSlug}`);
    if (!productId || !modelId) {
      skippedCompats += 1;
      continue;
    }
    await prisma.productCompatibility.upsert({
      where: { productId_modelId: { productId, modelId } },
      update: {},
      create: { productId, modelId },
    });
    seededCompats += 1;
  }

  const pairKey = (branchId: string, productId: string): string =>
    `${branchId}:${productId}`;
  const seededPairs = new Set<string>();
  let seededInventory = 0;
  let skippedInventory = 0;

  for (const row of mockInventory) {
    const productCode = row.productId.replace(/^p-/, "").toUpperCase();
    if (jsonStockByCode.has(productCode)) continue;
    const mockBranch = mockBranches.find((branch) => branch.id === row.branchId);
    const branch = mockBranch ? (branchByCode.get(mockBranch.code) ?? null) : null;
    const productId = productIdByCode.get(productCode);
    if (!branch || !productId) {
      skippedInventory += 1;
      continue;
    }
    const data = { quantity: row.quantity, reorderLevel: row.reorderLevel };
    await prisma.branchInventory.upsert({
      where: { branchId_productId: { branchId: branch.id, productId } },
      update: data,
      create: { ...data, branchId: branch.id, productId },
    });
    seededPairs.add(pairKey(branch.id, productId));
    seededInventory += 1;
  }

  const firstBranch = [...seededBranches].sort(
    (a, b) => a.displayOrder - b.displayOrder,
  )[0];
  if (firstBranch) {
    for (const product of seedProducts) {
      if (product.stock == null) continue;
      const productId = productIdByCode.get(product.code);
      if (!productId) continue;
      const key = pairKey(firstBranch.id, productId);
      if (seededPairs.has(key)) continue;
      const data = { quantity: product.stock, reorderLevel: null };
      await prisma.branchInventory.upsert({
        where: { branchId_productId: { branchId: firstBranch.id, productId } },
        update: data,
        create: { ...data, branchId: firstBranch.id, productId },
      });
      seededInventory += 1;
    }
  }

  let managersLinked = 0;
  for (const branch of seedBranches) {
    if (!branch.managerEmployeeNumber) continue;
    const employeeId = employeeByNumber.get(branch.managerEmployeeNumber);
    if (!employeeId) continue;
    await prisma.branch.update({
      where: { slug: branch.slug },
      data: { managerId: employeeId },
    });
    managersLinked += 1;
  }

  console.log("Seed complete:", {
    source: jsonBrands || jsonProducts ? "prisma/data/*.json" : "lib/mock (demo)",
    landingCategories: contentCategories.length,
    testimonials: testimonials.length,
    branches: seedBranches.length,
    employees: seedEmployees.length,
    brands: seedBrands.length,
    partCategories: seedCategories.length,
    models: seedModels.length,
    skippedModels,
    products: seedProducts.length,
    compatibilities: seededCompats,
    skippedCompats,
    inventoryRows: seededInventory,
    skippedInventory,
    managersLinked,
  });
}

main()
  .catch((error) => {
    console.error("Seed failed:", error);
    process.exit(1);
  })
  .finally(() => prisma.$disconnect());
